const fetch = require('node-fetch');
const searchQuery = $query;
const data = {
  "search": `${searchQuery}`,
  "country": "us",
  "language":"en",
  "cache": true,
  "store_data": true,
  "search_limit": 3,
  "depth": 1,
  "limit": 1,
  "proxy_enabled": true,
  "anti_bot": true,
  "request": "smart",
  "return_format": "text"
};

const url = 'https://api.spider.cloud/search';

try {
    const response = await fetch(url, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer SPIDER_API_KEY`, 
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(data)
    });
    if (!response.ok) {
        console.error('网络响应不正常:', response.statusText);
        return `错误: ${response.statusText}`; 
    }
    const text = await response.text(); 
    return text; 
} catch (error) {
    console.error(error);
    return ''; 
}

/*
 * 此工具对任何给定主题执行元搜索，并立即在单个API调用中抓取
 * 发现的URL。
 * 
 * 与OpenAI模型（gpt-4o和gpt-4o-mini）配合良好。
 * 与Google模型（Gemini）可能会出现不一致。
 * 其他模型未经测试。
 *
 * 关于搜索：
 * search（字符串）：您要搜索的查询。
 * country（字符串）：用于搜索的两字母国家代码。
 * language（字符串）：用于搜索的语言。
 * cache（布尔值）：使用HTTP缓存加速重复运行的抓取。
 * store_data（布尔值）：收集资源以供日后下载和重复使用。
 * search_limit（数字）：从搜索结果中获取的最大URL数量。
 *
 * 关于抓取：
 * depth（数字）：最大抓取深度（0表示无限制）。
 * limit（数字）：每个网站要抓取的最大页数。
 * proxy_enabled（布尔值）：启用高级代理进行抓取。
 * anti_bot（布尔值）：启用反机器人模式，使用技术提高成功率
 * request（字符串）：请求类型：'http'、'chrome'或'smart'。
 * return_format（字符串）：返回数据的格式。
 *
 * 更多选项：
 * https://spider.cloud/docs/api
 */
